export const COSMETIC_AUDIO = {"caseOpen":"./assets/cosmetics/audio/caseOpen.flac","caseScroll":"./assets/cosmetics/audio/caseScroll.flac","caseDisplay":"./assets/cosmetics/audio/caseDisplay.flac","revealRare":"./assets/cosmetics/audio/revealRare.flac","revealMythical":"./assets/cosmetics/audio/revealMythical.flac","revealLegendary":"./assets/cosmetics/audio/revealLegendary.flac","revealAncient":"./assets/cosmetics/audio/revealAncient.flac","revealSpecial":"./assets/cosmetics/audio/revealSpecial.flac"};

export const SKIN_BY_ID=Object.fromEntries(SKINS.map(s=>[s.id,s]));
export const CASE_BY_ID=Object.fromEntries(CASES.map(c=>[c.id,c]));
export const NATIVE_RARITIES={common:{name:'Consumer Grade',color:'#b0c3d9'},uncommon:{name:'Industrial Grade',color:'#5e98d9'},rare:{name:'Mil-Spec Grade',color:'#4b69ff'},mythical:{name:'Restricted',color:'#8847ff'},legendary:{name:'Classified',color:'#d32ce6'},ancient:{name:'Covert',color:'#eb4b4b'},unusual:{name:'Rare Special Item',color:'#e4ae39'}};
for(const skin of SKINS)skin.material=PAINT_MATERIALS[skin.paintName]||null;
const aliases={rifle:'ak47',pistol:'deagle'};
export function weaponSkins(key){return SKINS.filter(s=>s.weapon===(aliases[key]||key));}
export function wearName(value){const wear=Number(value);return WEAR_TIERS.find(t=>wear<t.max)?.name||'Battle-Scarred';}
export function finishPreview(skin,value=0){if(typeof skin==='string')skin=SKIN_BY_ID[skin];if(!skin)return '';const wear=Number(value);return skin.previews[wear<.15?'light':wear<.45?'medium':'heavy']||skin.preview;}
